// Generator for the Areson module device table.
// Usage: node scripts/openrgb/port-areson-devices.mjs <openrgb-root> <commit>
// Reads AresonControllerDetect.cpp and regenerates
// modules/areson/src/devices_table.rs. Do not edit by hand.
import fs from 'node:fs';
import path from 'node:path';
import { execFileSync } from 'node:child_process';

const root = process.argv[2] ?? process.env.OPENRGB_ROOT ?? '../openrgb';
const commit = process.argv[3] ?? 'unknown';
const family = path.join(root, 'Controllers', 'AresonController');
const detect = fs.readFileSync(path.join(family, 'AresonControllerDetect.cpp'), 'utf8');

const constants = Object.fromEntries(
  [...detect.matchAll(/#define\s+([A-Z][A-Z0-9_]*)\s+0x([0-9A-Fa-f]+)/g)].map((m) => [
    m[1],
    Number.parseInt(m[2], 16),
  ]),
);
if (constants.ARESON_VID == null) throw new Error('ARESON_VID not found');

const rows = [];
for (const m of detect.matchAll(
  /REGISTER_HID_DETECTOR(?:_IPU?)?\s*\(\s*"([^"]+)"\s*,\s*([A-Za-z0-9_]+)\s*,\s*ARESON_VID\s*,\s*([A-Z][A-Z0-9_]+)\s*(?:,\s*([^)]*)\))?/g,
)) {
  const pid = constants[m[3]];
  if (pid == null) throw new Error(`unresolved PID ${m[3]} in detector row ${m[1]}`);
  const args = (m[4] ?? '').split(',').map((s) => s.trim()).filter(Boolean);
  if (args.length === 3) {
    // _IPU: interface, usage page, usage
    rows.push({
      name: m[1],
      handler: m[2],
      vid: constants.ARESON_VID,
      pid,
      interface: Number.parseInt(args[0], 10),
      usagePage: Number.parseInt(args[1].replace(/^0x/i, ''), 16),
      usage: Number.parseInt(args[2].replace(/^0x/i, ''), 16),
    });
  } else {
    throw new Error(`unexpected detector args ${JSON.stringify(args)} in row ${m[1]}`);
  }
}
if (rows.length === 0) throw new Error('no Areson HID detectors parsed');

const out = path.join(process.cwd(), 'modules', 'areson', 'src', 'devices_table.rs');
const lines = [
  '// SPDX-License-Identifier: GPL-2.0-or-later',
  `// Generated by scripts/openrgb/port-areson-devices.mjs from OpenRGB ${commit}; do not edit.`,
  'use crate::table::Detector;',
  '',
  'pub const DETECTORS: &[Detector] = &[',
  ...rows.map(
    (d) =>
      `    Detector { name: ${JSON.stringify(d.name)}, handler: ${JSON.stringify(d.handler)}, vid: 0x${d.vid.toString(16).padStart(4, '0')}, pid: 0x${d.pid.toString(16).padStart(4, '0')}, interface: ${d.interface}, usage_page: 0x${d.usagePage.toString(16)}, usage: 0x${d.usage.toString(16)} },`,
  ),
  '];',
  '',
];
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, lines.join('\n'));
execFileSync(process.platform === 'win32' ? 'rustfmt.exe' : 'rustfmt', [out], { stdio: 'ignore' });
console.log(`generated ${rows.length} Areson HID detectors`);